mapper.select:
select d.id, d.name, c.id as categoryId, c.name as categoryName, group_concat(df.value) as flavors, d.price, d.image, d.description, d.status, d.update_time from sky_take_out.dish as d left join sky_take_out.dish_flavor as df on d.id = df.dish_id left join sky_take_out.category as c on d.category_id = c.id
d.category_name like concat('%', #{name}, '%')
d.category_id = #{categoryId} and d.status = #{status}
d.status = #{status}
group by d.id, d.category_id order by d.category_id
